-- TechSelectAI V1 MariaDB schema for shared hosting
-- Preserves the concepts from PostgreSQL migrations 001-006 while using MariaDB-compatible types.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS countries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code CHAR(2) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS industries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL UNIQUE,slug VARCHAR(190) UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL UNIQUE,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS modules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,description TEXT,is_active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_module(category_id,slug),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS capabilities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_id BIGINT UNSIGNED,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,description TEXT,is_security_related TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_capability(module_id,slug),KEY idx_cap_slug(slug),FOREIGN KEY(module_id) REFERENCES modules(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS integrations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL UNIQUE,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS deployment_models(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL UNIQUE,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vendors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,website_url TEXT,description TEXT,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vendor_id BIGINT UNSIGNED,category_id BIGINT UNSIGNED,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,short_description TEXT,website_url TEXT,status VARCHAR(32) NOT NULL DEFAULT 'active',last_reviewed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE SET NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_editions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,UNIQUE KEY uq_edition(product_id,slug),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_pricing(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,edition_id BIGINT UNSIGNED NULL,pricing_model VARCHAR(40) NOT NULL DEFAULT 'unknown',billing_period VARCHAR(40) NOT NULL DEFAULT 'unknown',currency CHAR(3),amount_min DECIMAL(14,2),amount_max DECIMAL(14,2),unit_label VARCHAR(100),notes TEXT,source_url TEXT,last_verified_at DATETIME,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(edition_id) REFERENCES product_editions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_capabilities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,capability_id BIGINT UNSIGNED NOT NULL,edition_id BIGINT UNSIGNED NULL,support_status VARCHAR(40) NOT NULL DEFAULT 'not_yet_verified',implementation_type VARCHAR(100),limitations TEXT,confidence_score DECIMAL(4,3) DEFAULT 0,last_verified_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_product_cap(product_id,capability_id,edition_id),KEY idx_cap_lookup(capability_id,support_status,product_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(capability_id) REFERENCES capabilities(id) ON DELETE CASCADE,FOREIGN KEY(edition_id) REFERENCES product_editions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS evidence_sources(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,source_type VARCHAR(40) NOT NULL,source_url TEXT,source_title VARCHAR(255) NOT NULL,publisher_name VARCHAR(190),vendor_owned TINYINT(1) NOT NULL DEFAULT 0,published_at DATETIME,checked_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,verification_status VARCHAR(32) NOT NULL DEFAULT 'unverified',confidence VARCHAR(16) NOT NULL DEFAULT 'medium',notes TEXT,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_capability_evidence(product_capability_id BIGINT UNSIGNED NOT NULL,evidence_source_id BIGINT UNSIGNED NOT NULL,is_primary TINYINT(1) NOT NULL DEFAULT 0,evidence_note TEXT,PRIMARY KEY(product_capability_id,evidence_source_id),FOREIGN KEY(product_capability_id) REFERENCES product_capabilities(id) ON DELETE CASCADE,FOREIGN KEY(evidence_source_id) REFERENCES evidence_sources(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(190) NOT NULL,role VARCHAR(32) NOT NULL DEFAULT 'user',status VARCHAR(32) NOT NULL DEFAULT 'pending',email_verified_at DATETIME,last_login_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS visitor_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_token_hash BINARY(32) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NULL,first_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,country_code CHAR(2),utm_source VARCHAR(190),utm_medium VARCHAR(190),utm_campaign VARCHAR(190),referrer TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS consultations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_token CHAR(48) NOT NULL UNIQUE,visitor_session_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,title VARCHAR(255),category_id BIGINT UNSIGNED NULL,business_problem TEXT NOT NULL,original_user_request TEXT,budget_min DECIMAL(14,2),budget_max DECIMAL(14,2),budget_currency CHAR(3),budget_period VARCHAR(50),implementation_timeline VARCHAR(100),preferred_deployment VARCHAR(100),status VARCHAR(32) NOT NULL DEFAULT 'draft',consultation_source VARCHAR(32) NOT NULL DEFAULT 'guided_wizard',started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(visitor_session_id) REFERENCES visitor_sessions(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS consultation_requirements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,consultation_id BIGINT UNSIGNED NOT NULL,capability_id BIGINT UNSIGNED NULL,requirement_text TEXT NOT NULL,normalized_requirement TEXT,priority VARCHAR(32) NOT NULL,is_mandatory TINYINT(1) NOT NULL DEFAULT 0,source VARCHAR(32) NOT NULL DEFAULT 'user_added',confidence_score DECIMAL(4,3),user_confirmed TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_req_consultation(consultation_id),FOREIGN KEY(consultation_id) REFERENCES consultations(id) ON DELETE CASCADE,FOREIGN KEY(capability_id) REFERENCES capabilities(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS consultation_integrations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,consultation_id BIGINT UNSIGNED NOT NULL,integration_id BIGINT UNSIGNED NOT NULL,priority VARCHAR(32) NOT NULL,is_mandatory TINYINT(1) NOT NULL DEFAULT 0,notes TEXT,UNIQUE KEY uq_consult_int(consultation_id,integration_id),FOREIGN KEY(consultation_id) REFERENCES consultations(id) ON DELETE CASCADE,FOREIGN KEY(integration_id) REFERENCES integrations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS consultation_recommendations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,consultation_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,recommendation_rank INT NOT NULL,overall_score DECIMAL(5,2) NOT NULL,functional_score DECIMAL(5,2) NOT NULL,mandatory_score DECIMAL(5,2) NOT NULL,integration_score DECIMAL(5,2) NOT NULL DEFAULT 100,deployment_score DECIMAL(5,2) NOT NULL DEFAULT 100,budget_score DECIMAL(5,2) NOT NULL DEFAULT 100,regional_score DECIMAL(5,2) NOT NULL DEFAULT 100,security_score DECIMAL(5,2) NOT NULL DEFAULT 100,evidence_score DECIMAL(5,2) NOT NULL DEFAULT 0,mandatory_gap_count INT NOT NULL DEFAULT 0,important_gap_count INT NOT NULL DEFAULT 0,recommendation_status VARCHAR(32) NOT NULL,generated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,scoring_version VARCHAR(32) NOT NULL,UNIQUE KEY uq_rec(consultation_id,product_id,scoring_version),FOREIGN KEY(consultation_id) REFERENCES consultations(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recommendation_gaps(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recommendation_id BIGINT UNSIGNED NOT NULL,consultation_requirement_id BIGINT UNSIGNED NULL,gap_type VARCHAR(32) NOT NULL,severity VARCHAR(16) NOT NULL,explanation TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(recommendation_id) REFERENCES consultation_recommendations(id) ON DELETE CASCADE,FOREIGN KEY(consultation_requirement_id) REFERENCES consultation_requirements(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ai_extraction_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,consultation_id BIGINT UNSIGNED NOT NULL,model_provider VARCHAR(50),model_name VARCHAR(100),prompt_version VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',raw_output JSON NOT NULL,confidence_score DECIMAL(4,3),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,reviewed_by_user_id BIGINT UNSIGNED NULL,FOREIGN KEY(consultation_id) REFERENCES consultations(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ai_follow_up_questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,consultation_id BIGINT UNSIGNED NOT NULL,extraction_run_id BIGINT UNSIGNED NULL,question_key VARCHAR(190) NOT NULL,question_text TEXT NOT NULL,reason TEXT NOT NULL,field_kind VARCHAR(40) NOT NULL,priority INT NOT NULL DEFAULT 100,status VARCHAR(32) NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,answered_at DATETIME NULL,KEY idx_ai_q(consultation_id,status,priority),FOREIGN KEY(consultation_id) REFERENCES consultations(id) ON DELETE CASCADE,FOREIGN KEY(extraction_run_id) REFERENCES ai_extraction_runs(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS=1;
